pub fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // Determine how many participants we will actually consider:
    let limit = participations.len().min(n as usize);

    // Count how many of the first `limit` participants are eligible.
    // A participant with attendance count `p` is eligible if 5 - p >= k.
    let eligible = participations
        .into_iter()
        .take(limit)
        .filter(|&p| 5u8.saturating_sub(p) >= k)
        .count() as u8;

    // We can form a team of 3 from 3 eligible participants.
    eligible / 3
}

#[cfg(test)]
mod tests {
    use super::solve;

    #[test]
    fn test_basic() {
        // Example: participations = [2, 3, 1, 5, 0]
        // k = 2 → need (5 - p) >= 2 → p ≤ 3
        // Eligible counts are p = 2,3,1,0 → 4 eligible → 4/3 = 1 team
        assert_eq!(solve(5, 2, vec![2, 3, 1, 5, 0]), 1);

        // If n is smaller than the length of the list, only first n are used
        // Here n = 3 → only [2,3,1], all three are eligible → 3/3 = 1
        assert_eq!(solve(3, 2, vec![2, 3, 1, 5, 0]), 1);

        // If n is larger, we process all available
        assert_eq!(solve(10, 1, vec![0, 1, 2, 3]), 1);
        // (5-p) >= 1 → p ≤ 4 → all four are eligible → 4/3 = 1

        // Edge cases
        assert_eq!(solve(0, 0, vec![0, 1, 2]), 0);   // no participants considered
        assert_eq!(solve(3, 5, vec![0, 5, 4]), 0);   // need (5-p) ≥ 5 → only p=0 qualifies, 1/3 = 0
        assert_eq!(solve(3, 0, vec![5, 5, 5]), 1);   // need (5-p) ≥ 0 → all qualify, 3/3 = 1
    }
}